import os, click
from click.testing import CliRunner

@click.command()
@click.option("--port", type=int)
def cli(port):
    click.echo(f"port={port}")

# discover the name click consults
seen = {}
class TracingEnviron:
    pass
orig = os.environ.get
def spy(key, *a, **k):
    if "PORT" in key or key.startswith("APP"):
        seen[key] = True
    return orig(key, *a, **k)
os.environ.get = spy

os.environ["APP__PORT"] = "8080"
r = CliRunner().invoke(cli, [], auto_envvar_prefix="APP")
print("get calls:", seen, "| output:", r.output, r.exception)
EOF

